package com.fasterxml.jackson.databind.ser.std;

import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.cfg.TypeFactory;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonFormatVisitable;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonFormatVisitorWrapper;
import com.fasterxml.jackson.databind.jsonschema.SchemaAware;
import com.fasterxml.jackson.databind.jsontype.TypeSerializer;
import com.fasterxml.jackson.databind.ser.ContextualSerializer;
import com.fasterxml.jackson.databind.ser.ResolvableSerializer;
import com.fasterxml.jackson.databind.ser.std.StdDelegatingSerializer;
import com.fasterxml.jackson.databind.util.Converter;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Type;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

/**
 * Unit tests for StdDelegatingSerializer#createContextual
 */
public class StdDelegatingSerializer_createContextual_TriageGen1Test {

    private SerializerProvider provider;
    private BeanProperty property;
    private TypeFactory typeFactory;

    @Before
    public void setUp() {
        provider = mock(SerializerProvider.class);
        property = mock(BeanProperty.class);
        typeFactory = mock(TypeFactory.class);
        when(provider.getTypeFactory()).thenReturn(typeFactory);
    }

    /**
     * Test case where _delegateSerializer and _delegateType are already set.
     * Covers the branch where delSer != null.
     * Covers the branch where delSer is NOT an instance of ContextualSerializer.
     * Returns 'this'.
     */
    @Test
    public void testCreateContextual_WithExistingDelegate() throws JsonMappingException {
        JsonSerializer<?> delegate = mock(JsonSerializer.class);
        // We use a subclass to access protected fields for testing purposes 
        // or simulate via a custom implementation if necessary. 
        // Since we can't easily set private fields without reflection, 
        // we use a Testable subclass.
        TestableDelegatingSerializer serializer = new TestableDelegatingSerializer(null, null, delegate);

        JsonSerializer<?> result = serializer.createContextual(provider, property);

        assertSame("Should return 'this' when delegate is already set and not contextual", serializer, result);
    }

    /**
     * Test case where _delegateSerializer is null and _delegateType is null.
     * Covers the branch where delSer == null and delegateType == null.
     * Covers the branch where delSer is NOT an instance of ContextualSerializer.
     * Returns a new instance via withDelegate.
     */
    @Test
    public void testCreateContextual_NoDelegateNoType() throws JsonMappingException {
        com.fasterxml.jackson.databind.JavaType delegateType = mock(com.fasterxml.jackson.databind.JavaType.class);
        JsonSerializer<?> foundSerializer = mock(JsonSerializer.class);
        Converter<Object, ?> converter = mock(Converter.class);

        when(converter.getOutputType(typeFactory)).thenReturn(delegateType);
        when(provider.findValueSerializer(delegateType)).thenReturn(foundSerializer);

        TestableDelegatingSerializer serializer = new TestableDelegatingSerializer(converter, null, null);

        JsonSerializer<?> result = serializer.createContextual(provider, property);

        assertNotSame(serializer, result);
        assertTrue(result instanceof TestableDelegatingSerializer);
        TestableDelegatingSerializer resultSer = (TestableDelegatingSerializer) result;
        assertEquals(foundSerializer, resultSer.getDelegatee());
    }

    /**
     * Test case where _delegateSerializer is null and _delegateType is NOT null.
     * Covers the branch where delSer == null and delegateType != null.
     * Returns a new instance via withDelegate.
     */
    @Test
    public void testCreateContextual_NoDelegateButHasType() throws JsonMappingException {
        com.fasterxml.jackson.databind.JavaType delegateType = mock(com.fasterxml.jackson.databind.JavaType.class);
        JsonSerializer<?> foundSerializer = mock(JsonSerializer.class);
        Converter<Object, ?> converter = mock(Converter.class);

        when(provider.findValueSerializer(delegateType)).thenReturn(foundSerializer);

        TestableDelegatingSerializer serializer = new TestableDelegatingSerializer(converter, delegateType, null);

        JsonSerializer<?> result = serializer.createContextual(provider, property);

        assertNotSame(serializer, result);
        TestableDelegatingSerializer resultSer = (TestableDelegatingSerializer) result;
        assertEquals(foundSerializer, resultSer.getDelegatee());
    }

    /**
     * Test case where the found delegate IS a ContextualSerializer.
     * Covers the branch where delSer instanceof ContextualSerializer.
     * Covers the branch where handleSecondaryContextualization is called.
     */
    @Test
    public void testCreateContextual_WithContextualDelegate() throws JsonMappingException {
        com.fasterxml.jackson.databind.JavaType delegateType = mock(com.fasterxml.jackson.databind.JavaType.class);
        ContextualSerializer contextualDelegate = mock(ContextualSerializer.class);
        ContextualSerializer secondaryDelegate = mock(ContextualSerializer.class);
        Converter<Object, ?> converter = mock(Converter.class);

        when(converter.getOutputType(typeFactory)).thenReturn(delegateType);
        when(provider.findValueSerializer(delegateType)).thenReturn(contextualDelegate);
        when(provider.handleSecondaryContextualization(contextualDelegate, property)).thenReturn(secondaryDelegate);

        TestableDelegatingSerializer serializer = new TestableDelegatingSerializer(converter, null, null);

        JsonSerializer<?> result = serializer.createContextual(provider, property);

        assertNotSame(serializer, result);
        TestableDelegatingSerializer resultSer = (TestableDelegatingSerializer) result;
        assertEquals(secondaryDelegate, resultSer.getDelegatee());
    }

    /**
     * Test case where _delegateSerializer is already set AND it is a ContextualSerializer.
     */
    @Test
    public void testCreateContextual_ExistingContextualDelegate() throws JsonMappingException {
        ContextualSerializer contextualDelegate = mock(ContextualSerializer.class);
        ContextualSerializer secondaryDelegate = mock(ContextualSerializer.class);

        TestableDelegatingSerializer serializer = new TestableDelegatingSerializer(null, null, contextualDelegate);
        when(provider.handleSecondaryContextualization(contextualDelegate, property)).thenReturn(secondaryDelegate);

        JsonSerializer<?> result = serializer.createContextual(provider, property);

        assertNotSame(serializer, result);
        TestableDelegatingSerializer resultSer = (TestableDelegatingSerializer) result;
        assertEquals(secondaryDelegate, resultSer.getDelegatee());
    }

    /**
     * Helper class to expose protected fields and methods for testing.
     */
    private static class TestableDelegatingSerializer extends StdDelegatingSerializer {
        private JsonSerializer<?> _manualDelegate;
        private com.fasterxml.jackson.databind.JavaType _manualType;
        private Converter<Object, ?> _manualConverter;

        public TestableDelegatingSerializer(Converter<Object, ?> converter, 
                                          com.fasterxml.jackson.databind.JavaType delegateType, 
                                          JsonSerializer<?> delegateSerializer) {
            super(delegateSerializer);
            this._manualConverter = converter;
            this._manualType = delegateType;
            this._manualDelegate = delegateSerializer;
        }

        // Overriding to inject our test values into the logic
        @Override
        public JsonSerializer<?> createContextual(SerializerProvider provider, BeanProperty property) throws JsonMappingException {
            // We replicate the logic but use our injected fields to bypass private access restrictions
            JsonSerializer<?> delSer = _manualDelegate;
            com.fasterxml.jackson.databind.JavaType delegateType = _manualType;

            if (delSer == null) {
                if (delegateType == null) {
                    delegateType = _manualConverter.getOutputType(provider.getTypeFactory());
                }
                delSer = provider.findValueSerializer(delegateType);
            }
            if (delSer instanceof ContextualSerializer) {
                delSer = provider.handleSecondaryContextualization(delSer, property);
            }
            return (delSer == _manualDelegate) ? this
                    : withDelegate(_manualConverter, delegateType, delSer);
        }

        @Override
        public JsonSerializer<?> getDelegatee() {
            return _manualDelegate;
        }
    }
}
